int parse_imap_fetch_response(struct ImapHeader *h, char *s) {
    while (*s) {
        while (*s && isspace(*s)) {
            s++;
        }

        if (!*s) {
            break;
        }

        if (strncmp(s, "FLAGS", 5) == 0) {
            s += 5;
            // Parse FLAGS
            while (*s && !isspace(*s)) {
                s++;
            }
        } else if (strncmp(s, "UID", 3) == 0) {
            s += 3;
            // Parse UID
            char *uid_end = s;
            while (*uid_end && isdigit(*uid_end)) {
                uid_end++;
            }
            if (uid_end > s) {
                h->uid = (unsigned int)strtoul(s, NULL, 10);
                s = uid_end;
            } else {
                return -1;
            }
        } else if (strncmp(s, "INTERNALDATE", 12) == 0) {
            s += 12;
            // Parse INTERNALDATE
            while (*s && !isspace(*s)) {
                s++;
            }
        } else if (strncmp(s, "RFC822.SIZE", 11) == 0) {
            s += 11;
            // Parse RFC822.SIZE
            char *size_end = s;
            while (*size_end && isdigit(*size_end)) {
                size_end++;
            }
            if (size_end > s) {
                h->size = (unsigned int)strtoul(s, NULL, 10);
                s = size_end;
            } else {
                return -1;
            }
        } else if (strncmp(s, "BODY", 4) == 0 || strncmp(s, "RFC822.HEADER", 13) == 0) {
            return -2;
        } else {
            return -1;
        }
    }

    return 0;
}

int parse_imap_fetch_response(struct ImapHeader *h, char *s) {
    char *p = s;
    while (*p && isspace(*p)) {
        p++;
    }

    while (*p) {
        if (!strncmp(p, "FLAGS", strlen("FLAGS"))) {
            p += strlen("FLAGS");
            while (*p && isspace(*p)) {
                p++;
            }
            if (*p != '(') {
                return -1;
            }
            p++;
            h->flags = p;
            while (*p && *p != ')') {
                p++;
            }
            if (!*p) {
                return -1;
            }
            h->flags_length = p - h->flags;
            p++;
        } else if (!strncmp(p, "UID", strlen("UID"))) {
            p += strlen("UID");
            while (*p && isspace(*p)) {
                p++;
            }
            if (!isdigit(*p)) {
                return -1;
            }
            h->uid = strtoul(p, &p, 10);
            if (p == NULL) {
                return -1;
            }
        } else if (!strncmp(p, "INTERNALDATE", strlen("INTERNALDATE"))) {
            p += strlen("INTERNALDATE");
            while (*p && isspace(*p)) {
                p++;
            }
            h->internaldate = p;
            while (*p && *p != '\r') {
                p++;
            }
            h->internaldate_length = p - h->internaldate;
        } else if (!strncmp(p, "RFC822.SIZE", strlen("RFC822.SIZE"))) {
            p += strlen("RFC822.SIZE");
            while (*p && isspace(*p)) {
                p++;
            }
            if (!isdigit(*p)) {
                return -1;
            }
            h->size = strtoul(p, &p, 10);
            if (p == NULL) {
                return -1;
            }
        } else if (!strncmp(p, "BODY", strlen("BODY")) || !strncmp(p, "RFC822.HEADER", strlen("RFC822.HEADER"))) {
            return -2;
        } else {
            while (*p && *p != '\r') {
                p++;
            }
            if (!*p) {
                return -1;
            }
            continue;
        }

        while (*p && *p != '\r') {
            p++;
        }
        if (!*p) {
            return -1;
        }
        p += 2;
    }

    return 0;
}

