    char *ptr = s;
    char field[256];
    int field_index = 0;
    int in_quoted = 0;
    int in_value = 0;

    while (*ptr) {
        if (*ptr == ' ' || *ptr == '\t') {
            if (in_value && !in_quoted) {
                *ptr = '\0';
                in_value = 0;
            }
            ptr++;
            continue;
        }

        if (!in_value) {
            if (*ptr == '"') {
                in_quoted = !in_quoted;
                ptr++;
                continue;
            }

            if (field_index < sizeof(field) - 1) {
                field[field_index++] = *ptr;
            }
            ptr++;
            in_value = 1;
        } else {
            if (*ptr == '"') {
                in_quoted = !in_quoted;
                ptr++;
                continue;
            }

            if (!in_quoted && (*ptr == ' ' || *ptr == '\t')) {
                *ptr = '\0';
                in_value = 0;
                field[field_index] = '\0';
                field_index = 0;

                if (strncmp(field, "FLAGS", sizeof("FLAGS") - 1) == 0) {
                    // Parse flags
                    char *value = ptr + 1;
                    // Extract and process flags
                } else if (strncmp(field, "UID", sizeof("UID") - 1) == 0) {
                    long long uid = strtoll(ptr + 1, NULL, 10);
                    h->uid = (unsigned int)uid;
                } else if (strncmp(field, "INTERNALDATE", sizeof("INTERNALDATE") - 1) == 0) {
                    // Parse and store date
                    char *value = ptr + 1;
                    strncpy(h->internal_date, value, sizeof(h->internal_date) - 1);
                    h->internal_date[sizeof(h->internal_date) - 1] = '\0';
                } else if (strncmp(field, "RFC822.SIZE", sizeof("RFC822.SIZE") - 1) == 0) {
