                           strncmp(field, "RFC822.HEADER", sizeof("RFC822.HEADER") - 1) == 0) {
                    return -2;
                } else {
                    // Unrecognized field
                    return -1;
                }
            } else {
                ptr++;
            }
        }
    }

    if (in_value && field_index > 0) {
        field[field_index] = '\0';
        if (strncmp(field, "FLAGS", sizeof("FLAGS") - 1) == 0) {
            // Parse flags
            char *value = ptr;
            // Extract and process flags
        } else if (strncmp(field, "UID", sizeof("UID") - 1) == 0) {
            long long uid = strtoll(ptr, NULL, 10);
            h->uid = (unsigned int)uid;
        } else if (strncmp(field, "INTERNALDATE", sizeof("INTERNALDATE") - 1) == 0) {
            // Parse and store date
            strncpy(h->internal_date, ptr, sizeof(h->internal_date) - 1);
            h->internal_date[sizeof(h->internal_date) - 1] = '\0';
        } else if (strncmp(field, "RFC822.SIZE", sizeof("RFC822.SIZE") - 1) == 0) {
            long size = strtol(ptr, NULL, 10);
            h->size = (unsigned int)size;
        } else if (strncmp(field, "BODY", sizeof("BODY") - 1) == 0 ||
                   strncmp(field, "RFC822.HEADER", sizeof("RFC822.HEADER") - 1) == 0) {
            return -2;
        } else {
            // Unrecognized field
            return -1;
        }
    }

    return 0;
}

int parse_imap_fetch_response(struct ImapHeader *h, char *s) {
    char *ptr = s;
    while (*ptr && isspace(*ptr)) {
        ptr++;
    }

    while (*ptr) {
        if (strncmp(ptr, "FLAGS", 5) == 0) {
            ptr += 5;
            // Skip to the opening parenthesis
            while (*ptr && *ptr != '(') {
                ptr++;
            }
            if (*ptr == '(') {
                ptr++;
                h->flags = ptr;
                // Find the end of the flags section
                while (*ptr && *ptr != ')') {
                    ptr++;
                }
                if (*ptr == ')') {
                    *ptr = '\0';
                    ptr++;
                }
            }
        } else if (strncmp(ptr, "UID", 3) == 0) {
            ptr += 3;
            while (*ptr && isspace(*ptr)) {
                ptr++;
            }
            if (isdigit(*ptr)) {
                h->uid = atoi(ptr);
                while (*ptr && isdigit(*ptr)) {
                    ptr++;
                }
            } else {
                return -1;
            }
        } else if (strncmp(ptr, "INTERNALDATE", 12) == 0) {
            ptr += 12;
            while (*ptr && isspace(*ptr)) {
                ptr++;
            }
            if (*ptr == '{') {
                ptr++;
                h->internaldate = ptr;
                while (*ptr && *ptr != '}') {
                    ptr++;
                }
                if (*ptr == '}') {
                    *ptr = '\0';
                    ptr++;
                }
            } else {
                return -1;
            }
        } else if (strncmp(ptr, "RFC822.SIZE", 11) == 0) {
            ptr += 11;
            while (*ptr && isspace(*ptr)) {
                ptr++;
            }
            if (isdigit(*ptr)) {
                h->rfc822_size = atoi(ptr);
                while (*ptr && isdigit(*ptr)) {
                    ptr++;
                }
            } else {
                return -1;
            }
        } else if (strncmp(ptr, "BODY", 4) == 0 || strncmp(ptr, "RFC822.HEADER", 13) == 0) {
            return -2;
        } else {
            return -1;
        }

        while (*ptr && isspace(*ptr)) {
            ptr++;
        }
    }

    return 0;
}

int parse_imap_fetch_response(struct ImapHeader *h, char *s) {
    char *ptr = s;
    int in_field = 0;
    char field_name[64];
    char *field_value = NULL;
    int field_name_len = 0;

    while (*ptr) {
        if (in_field) {
            if (*ptr == '\0' || *ptr == '\r' || *ptr == '\n' || *ptr == ' ' || *ptr == '\t') {
                *ptr = '\0';
                in_field = 0;

                // Process field name and value
                if (strncmp(field_name, "FLAGS", field_name_len) == 0) {
                    // Skip "("
                    if (*(ptr + 1) != '(') {
                        return -1;
                    }
                    ptr += 2;
                    char *end = ptr;
                    while (*end && *end != ')') {
                        end++;
                    }
                    if (!*end) {
                        return -1;
                    }
                    *end = '\0';
                    // For simplicity, we'll store a copy of flags string
                    if (h->flags)
                        free(h->flags);
                    h->flags = strdup(ptr);
                } else if (strncmp(field_name, "UID", field_name_len) == 0) {
                    char *end;
                    long val = strtol(ptr, &end, 10);
                    if (end == ptr || *end != '\0') {
                        return -1;
                    }
                    h->uid = val;
                } else if (strncmp(field_name, "INTERNALDATE", field_name_len) == 0) {
                    // Skip opening quote
                    if (*ptr != '"') {
                        return -1;
                    }
                    ptr++;
                    char *end = ptr;
                    while (*end && *end != '"') {
                        end++;
                    }
                    if (!*end) {
                        return -1;
                    }
                    *end = '\0';
                    if (h->internaldate)
                        free(h->internaldate);
                    h->internaldate = strdup(ptr);
                } else if (strncmp(field_name, "RFC822.SIZE", field_name_len) == 0) {
                    char *end;
                    long val = strtol(ptr, &end, 10);
                    if (end == ptr || *end != '\0') {
                        return -1;
                    }
                    h->rfc822_size = val;
                } else if (strncmp(field_name, "BODY", field_name_len) == 0 || strncmp(field_name, "RFC822.HEADER", field_name_len) == 0) {
                    return -2;
                } else {
                    return -1;
                }
            }
        } else {
            if (*ptr == ' ' || *ptr == '\t') {
                ptr++;
                continue;
            } else if (*ptr == '\r' || *ptr == '\n') {
                ptr++;
                continue;
            } else if (*ptr == '(' || *ptr == ')' || *ptr == '"') {
                ptr++;
                continue;
            } else if (isalnum(*ptr)) {
                field_name[field_name_len++] = toupper(*ptr);
                in_field = 1;
                ptr++;
            } else {
                return -1;
            }
        }
        ptr++;
    }

    return 0;
}
